INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('fcffedcb926fd9cff31d256c6071383a198d3262e3541b7dfd7a00040405cce3', 'NEW FORMAT GETS RAVE REVIEWS / SHOWIN'' IT OFF', 'MSU_Clippings', '/api/assets/documents/fcffedcb926fd9cff31d256c6071383a198d3262e3541b7dfd7a00040405cce3.pdf', 'document', 'ingested', '{"date": "1991-09", "description": "This excerpt from the September\u2013October 1991 newsletter of the Uncircumcised Society of America - New York (USA - NY) reports positive member feedback regarding the newsletter''s updated design and visual layout. The piece includes comments from members celebrating the inclusion of graphics and photographs of intact male anatomy, alongside submission guidelines and camera recommendations for members wishing to submit photos for publication.", "source": "MSU_Clippings", "academic_title": "NEW FORMAT GETS RAVE REVIEWS / SHOWIN'' IT OFF", "abstract": "A brief newsletter segment from the Uncircumcised Society of America - New York chapter detailing member reception to a newly redesigned newsletter format. The text highlights endorsements from charter members and provides technical photography tips (including recommended Polaroid camera models and framing instructions) for members submitting erotic or anatomical photographs showcasing the foreskin.", "source_publication": "Uncircumcised Society of America - New York Newsletter", "author": "Uncircumcised Society of America - New York", "citations": [], "keywords": ["Uncircumcised Society of America", "intact foreskin", "newsletter", "member submissions", "photography tips", "Polaroid"], "category": "Activism", "media_types": ["Text"], "document_type": "Document", "key_people": ["Gene Sowder", "Bill Schilling", "Bill F. James", "Bill P. James", "Ricky Carr", "Mac"], "organizations": ["Uncircumcised Society of America - New York", "USA - NY"], "themes": ["Foreskin Pride", "Intact Body Positivity", "Community Building", "Am