INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('74d3ecefb751cf6912c698cba2fc847922570b1f9595795e5200748f5e5d4e81', 'USA - NY: Playin'' It Safe / Uncut Hollywood / Uncut Dallas Gets Down', 'MSU_Clippings', '/api/assets/documents/74d3ecefb751cf6912c698cba2fc847922570b1f9595795e5200748f5e5d4e81.pdf', 'document', 'ingested', '{"date": "1991", "description": "This excerpt from an early 1990s newsletter published by USA-NY, an organization celebrating intact (uncircumcised) men, highlights club updates, pop culture trivia, and community news. It features a brief acknowledgment of reader photos modeling safe sex practices, a discussion regarding the circumcision status of actor Perry King in various film appearances, and a report on the evolution of member meetings from formal business sessions to uninhibited, low-risk safe-sex gatherings in Greenwich Village. The article also notes that a affiliated group, Uncut Dallas, adopted a similar transition toward safe-sex club programming following a member survey.", "source": "MSU_Clippings", "academic_title": "USA - NY: Playin'' It Safe / Uncut Hollywood / Uncut Dallas Gets Down", "abstract": "This document consists of newsletter excerpts published by the New York chapter of the Uncut Society/USA-NY dating to circa late 1991. The text explores gay social organizing, community health adaptations, and foreskin cultural iconography during the HIV/AIDS epidemic. Key topics include debates over celebrity genital intactness in vintage adult cinema, promotion of condom use, and the intentional shift of male social clubs in New York and Dallas from structured administrative assemblies to sex-positive, low-risk social venues.", "source_publication": "USA - NY Newsletter", "author": "USA - NY", "citations": ["Ward, L.E. (1991, September). Celebrity Skin, Part II. Uncut.", "Mandingo (1975 film).", "Who''s Got the Ball? (Retro-Vid release).", "UNCUT DALLAS Newsletter (Summer 1991 issue)."], "keywords": ["Circumcision", "Uncut men", "USA-NY", "Uncut Dallas", "Safe sex", "Greenwich Village", "Gay social clubs", "Foreskin"], "category": "Activism", "media_types": ["Text"], "document_type": "Document", "key_people": ["Perry King", "Johnny Holmes", "L.E. Ward", "DrG"], "organizations": ["USA - NY", "UNCUT DALLAS", "Retro-Vid"], "themes": ["Foreskin advocacy and community building", "Safe sex culture during the HIV/AIDS epidemic", "Celebrity body culture", "Gay male socializing in urban spaces"], "physical_provenance": {"original_collection": null, "holding_institution": null, "folder_number": null, "archive_subject": null}}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a52fd74c80e3c54cf455968ccc3b8e85e879e6b8e15ac247bb5809e8542a5b4a', 'The Party''s Over in the Village / Spotlight on Uncut Dallas', 'MSU_Clippings', '/api/assets/documents/a52fd74c80e3c54cf455968ccc3b8e85e879e6b8e15ac247bb5809e8542a5b4a.pdf', 'document', 'ingested', '{"date": "1991", "description": "This excerpt from page 3 of the USA-NY newsletter highlights fraternal relations and shared safe-sex philosophies between the New York-based organization and UNCUT DALLAS, an organization for uncircumcised gay men and foreskin enthusiasts. The text presents survey results from the Summer 1991 UNCUT DALLAS Newsletter documenting member interests in safe-sex guidelines, personal ads, and foreskin restoration information. Additionally, the article ''The Party''s Over in the Village'' details logistical challenges facing USA-NY after host Gene Sowder faced scrutiny and complaints from co-op tenants in Greenwich Village following a disruptive visitor incident, necessitating a reduction in weekly gatherings and a search for alternative meeting venues.", "source": "MSU_Clippings", "academic_title": "The Party''s Over in the Village / Spotlight on Uncut Dallas", "abstract": "This archival newsletter excerpt from the gay intact-men fraternity USA-NY covers organizational updates, safe-sex culture, and community networking during 1991. The document profiles peer organization UNCUT DALLAS, reviewing its club policies, distribution of condoms, and member survey data on interest in uncut-related media, erotic fiction, and foreskin restoration. The newsletter also reports on domestic space constraints in New York City, detailing how residential neighborhood friction in a Greenwich Village co-op forced USA-NY to curtail weekly meetings at organizer Gene Sowder''s apartment and seek decentralized hosting arrangements among members.", "source_publication": "USA - NY Newsletter", "author": "USA - NY", "citations": ["UNCUT DALLAS Newsletter Vol. 7, No. 2: Summer 1991"], "keywords": ["USA - NY", "UNCUT DALLAS", "Foreskin", "Uncircumcised Gay Men", "Safe Sex", "Foreskin Restoration", "Greenwich Village", "Gene Sowder"], "category": "Activism", "media_types": ["Text"], "document_type": "Document", "key_people": ["Gene Sowder"], "organizations": ["USA - NY", "UNCUT DALLAS"], "themes": ["Safe-sex club culture and condom distribution", "Gay male fraternities and foreskin appreciation", "Community organizing and venue displacement"], "physical_provenance": {"original_collection": null, "holding_institution": null, "folder_number": null, "archive_subject": null}}');
