INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8f1fa5d57955060ea401c8d4e919ec5a7c7de884651117495036f112b98c41f4', 'Video Views: Club Mandom and Uncut Rx', 'MSU_Clippings', '/api/assets/documents/8f1fa5d57955060ea401c8d4e919ec5a7c7de884651117495036f112b98c41f4.pdf', 'document', 'ingested', '{"date": "1991", "description": "This document features a review column titled ''Video Views,'' evaluating two adult video releases by Surge Studio\u2014''Club Mandom, Part I'' (subtitled ''Blue Collar Cheese Factory'') and ''Club Mandom, Part II'' (''Cock Lips''). The reviewer examines the films'' depiction of uncircumcised men, oral sex, and thematic fantasies, while noting the presence of smegma in the first release. Accompanying the film critique is a brief reader photo acknowledgment and an informational health advisory titled ''UNCUT Rx.''\n\n''UNCUT Rx'' provides a concise physiological overview of smegma, defining it as a secretion of the preputial (Tyson''s) glands situated beneath the foreskin. The advisory notes that while smegma can produce an odor and cause irritation or inflammation of the glans if left unwashed, routine penile hygiene effectively manages it. The page concludes with the advocacy slogan, ''May the foreskin be with you.''", "source": "MSU_Clippings", "academic_title": "Video Views: Club Mandom and Uncut Rx", "abstract": "This archival excerpt comprises adult entertainment reviews, reader correspondence, and anatomical hygiene advice aimed at an audience interested in intact male anatomy. The primary segment, ''Video Views,'' assesses two 75-minute adult videos from Surge Studio (''Club Mandom, Part I'' and ''Part II'') focusing on glory hole encounters featuring uncircumcised men, with explicit commentary on production aesthetics and viewer expectations regarding penile hygiene. A companion educational sidebar, ''UNCUT Rx,'' defines smegma and its origin in preputial secretions, detailing potential complications such as localized irritation and emphasizing standard hygiene for the intact penis.", "source_publication": null, "author": null, "citations": ["Club Mandom, Part I: Blue Collar Cheese Factory (Surge Studio)", "Club Mandom, Part II: Cock Lips (Surge Studio)", "Wide Load"], "keywords": ["Foreskin", "Uncircumcised", "Smegma", "Prepuce", "Tyson''s Glands", "Adult Film Reviews", "Surge Studio", "Men''s Health", "Penile Hygiene"], "category": "Sexuality & Health", "media_types": ["Text", "Image"], "document_type": "Document", "key_people": ["Jon King", "David Ashfield", "Ricky"], "organizations": ["Surge Studio"], "themes": ["Intact Penile Aesthetics and Eroticism", "Adult Film Criticism", "Foreskin Care and Hygiene", "Gay Male Sexuality"], "physical_provenance": {"original_collection": null, "holding_institution": null, "folder_number": null, "archive_subject": null}}');
