INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('61e7f718c91b2f33638f5fb59f9876ad3abc0609af4639ec29f26236076f11bb', 'A New Year for USA-NY: Uncircumcised Society of America - New York Newsletter', 'MSU_Clippings', '/api/assets/documents/61e7f718c91b2f33638f5fb59f9876ad3abc0609af4639ec29f26236076f11bb.pdf', 'document', 'ingested', '{"date": "1992-03-01", "description": "This document is a page from the March\u2013April 1992 newsletter of the Uncircumcised Society of America - New York (USA-NY). It announces the start of the organization''s new membership year on March 1, calling on members to renew their annual memberships and newsletter subscriptions, and includes a survey asking for feedback on content. It also advertises weekly Friday night social gatherings held at President Gene Sowder''s Manhattan apartment, noting admission policies, hygiene requests, and a call for new, younger members.", "source": "MSU_Clippings", "academic_title": "A New Year for USA-NY: Uncircumcised Society of America - New York Newsletter", "abstract": "The March\u2013April 1992 bulletin from the Uncircumcised Society of America - New York chapter (USA-NY) outlines organizational updates, leadership contact information, and membership renewal procedures. Serving as both a community circular and social notice, the publication describes regular Friday evening meetings, entry requirements, and behavioral expectations for attendees. Additionally, editorial commentary reflects member feedback regarding the newsletter''s recent redesign, personals section, and graphic photographic content, illustrating gay and intact-men community subcultures in early 1990s New York City.", "source_publication": "USA - NY Newsletter", "author": "Uncircumcised Society of America - New York", "citations": [], "keywords": ["Uncircumcised Society of America", "USA-NY", "Foreskin", "Circumcision", "Intact Men", "Social Club", "Gay Community", "New York City"], "category": "Activism", "media_types": ["Text", "Image"], "document_type": "Document", "key_people": ["Gene Sowder", "Bill F. James", "Bill P. James", "Ray", "Ricky C"], "organizations": ["Uncircumcised Society of America - New York", "USA - NY", "Two Creative Guys"], "themes": ["Foreskin Advocacy and Appreciation", "Social and Support Networks for Intact Men", "Community Building in 1990s New York City"], "physical_provenance": {"original_collection": null, "holding_institution": null, "folder_number": null, "archive_subject": null}}');
